RECORDS = [('医学微生物的分类与尺度', '微生物基础', '绪论', '细菌为原核细胞，真菌为真核生物，病毒缺乏完整的细胞结构并依赖宿主完成复制。分类依据结构和遗传等特征，致病性不能仅由大小或名称推定。', ['能比较细菌、真菌和病毒的基本组织。', '能区分生物分类与致病性判断。'], Q('下列哪类病原体缺乏完整细胞结构，并依赖宿主细胞复制？', '病毒', ['细菌', '酵母型真菌', '丝状真菌'], '病毒没有完整细胞结构，其复制利用宿主细胞系统。'), Q('显微研究发现某微生物具有真正细胞核及膜性细胞器，分类时可先排除哪组？', '典型细菌和病毒', ['酵母型真菌和霉菌', '单细胞真核微生物', '具有细胞壁的真核微生物'], '真正细胞核和膜性细胞器提示真核细胞；典型细菌为原核，病毒无完整细胞结构。')), ('细菌细胞壁与革兰染色', '细菌学基础', '细菌的形态与结构', '细菌细胞壁维持形态并与宿主反应有关。典型革兰阳性菌和阴性菌的壁结构不同；阴性菌外膜含脂多糖，革兰染色结果需结合菌龄及方法等条件解释。', ['能比较典型两类细胞壁。', '能区分外膜与细胞质膜。'], Q('典型革兰阴性菌中，脂多糖主要位于哪种结构？', '外膜', ['细胞质膜内侧', '肽聚糖层的主体骨架', '细胞外荚膜的全部组成'], '脂多糖是典型革兰阴性菌外膜的重要成分，脂质A与内毒素效应相关。'), Q('关于典型革兰阳性菌与阴性菌，哪项比较正确？', '阳性菌肽聚糖层通常较厚，阴性菌有外膜', ['阴性菌完全没有肽聚糖', '阳性菌必定具有含脂多糖的外膜', '两者都具有真正细胞核'], '两类的细胞壁组织不同；不能把阴性菌外膜与细胞质膜混同。'), [(1, '理解原核细胞结构是细菌壁比较的基础')]), ('细菌生长、繁殖与培养条件', '细菌学基础', '细菌的生理主题', '细菌主要以二分裂繁殖，群体在有限培养条件下可表现为延缓、对数、稳定和衰亡等阶段。氧、营养及温度要求因微生物而异，体外培养阴性不等同于绝对不存在病原体。', ['能解释二分裂和群体增长。', '能区分培养条件限制与存在性判断。'], Q('理想条件下，一个细菌连续完成3次二分裂且无死亡，可得到多少个细菌？', '8个', ['3个', '6个', '9个'], '每代数量加倍，1×2³=8。'), Q('某培养系统未检出微生物，最合理的解释原则是什么？', '需考虑标本、培养条件和检测能力，不能仅凭阴性排除一切微生物', ['所有微生物均能在同一种培养基中生长', '阴性直接证明采样前从无微生物', '病毒一定会像普通细菌一样在无细胞培养基增殖'], '可培养性受微生物特性和方法影响，阴性结果具有方法学边界。'), [(1, '不同微生物的结构与生活方式决定培养要求')]), ('细菌遗传变异与耐药传播', '细菌学基础', '细菌的遗传与变异主题', '突变和水平基因转移可改变细菌性状，转化、转导、接合具有不同转移机制。耐药性涉及靶点、药物进入与排出、灭活等因素，选择压力与基因传播共同影响群体变化。', ['能区分三类水平转移方式。', '能说明选择与耐药基因传播的区别。'], Q('由噬菌体介导细菌遗传物质转移的过程叫什么？', '转导', ['转化', '接合', '二分裂'], '转导以噬菌体为介导者；转化涉及摄取游离DNA，接合涉及细胞间相关接触和转移装置。'), Q('某细菌获得携带耐药基因的质粒，且需与供体细菌接触，最符合哪种机制？', '接合', ['噬菌体介导的转导', '摄取环境游离DNA的转化', '仅靠细胞分裂而无遗传物质转移'], '接合可介导质粒等遗传成分在细菌间转移；是否带特定基因仍需相应检测。'), [(2, '细菌结构有助于理解物质进入和细胞间转移', 'soft')]), ('细菌致病性、毒素与宿主反应', '宿主与微生物', '细菌的感染与免疫主题', '致病过程涉及进入、黏附、侵袭、毒素及宿主反应等环节。外毒素通常为分泌或释放的蛋白质毒素；内毒素主要关联革兰阴性菌脂多糖，不能把两者按毒性大小简单分类。', ['能区分外毒素与内毒素的基本物质属性。', '能说明感染结果受宿主与病原共同影响。'], Q('典型革兰阴性菌内毒素效应主要与脂多糖中的哪个部分有关？', '脂质A', ['O特异多糖', '核心多糖', '肽聚糖'], '脂多糖中脂质A与主要内毒素生物学活性有关。'), Q('同一微生物在不同宿主体内造成不同结局，最合适的解释是什么？', '病原特征、进入部位与宿主防御等共同影响结果', ['只要菌名相同，所有宿主结局必须完全相同', '微生物剂量和进入途径从不影响结果', '所有损伤都只来自病原直接破坏而无宿主反应'], '感染是病原与宿主互动过程，免疫反应既可防御也可能参与组织损伤。'), [(2, '脂多糖位置和性质是理解内毒素的基础')]), ('人体微生物群、定植与机会致病', '宿主与微生物', '人体微生物群', '人体不同部位存在不同微生物群，可参与代谢及防御。定植与感染需区分；菌群失衡、屏障改变或宿主防御减弱时，某些原有微生物可成为机会致病因素。', ['能区分定植与感染。', '能说明微生物与宿主关系依赖部位和条件。'], Q('在某部位检出微生物但无相应疾病证据时，首先应避免哪种推断？', '直接把检出等同于该微生物导致疾病', ['考虑正常定植的可能', '结合标本来源判断', '比较症状及其他检测证据'], '检出、定植、感染和致病不是同义词，需结合场所与证据。'), Q('某肠道常见微生物进入通常无菌的组织后引起炎症，主要体现什么？', '同一微生物的作用与所在部位及宿主条件相关', ['正常定植微生物永远不可能致病', '菌群中所有成员都应被视为相同病原', '检出任意微生物即能确定感染严重度'], '机会致病可由移位和防御变化产生，不能以既往正常定植身份否定其条件性致病。'), [(5, '先理解宿主—病原互动，再比较定植与机会感染')]), ('病毒结构、基因组与包膜', '病毒学', '病毒的基本性状主题', '病毒颗粒一般由核酸基因组和衣壳构成，部分具有包膜。基因组类型与复制方式有关；包膜与无包膜病毒的环境稳定性常有差异，但不能脱离具体病毒作绝对推断。', ['能区分衣壳与包膜。', '能将基因组类型与复制策略联系。'], Q('病毒衣壳主要由什么构成？', '蛋白质', ['脂质双层及相关糖蛋白', '肽聚糖网格', '核酸本身形成的外层壳'], '衣壳为包裹基因组的蛋白质结构；包膜则通常来自细胞膜并含病毒相关成分。'), Q('关于病毒包膜，哪项正确？', '部分病毒具有包膜，它与衣壳不是同一结构', ['所有病毒必然具有包膜', '包膜等同于细菌肽聚糖壁', '无包膜病毒一定不能感染细胞'], '包膜存在与否是结构特点之一，不能单靠这一点判断全部致病或稳定性特征。'), [(1, '需先区分病毒与完整细胞型微生物')]), ('病毒复制与感染结局', '病毒学', '病毒的感染与免疫主题', '病毒复制涉及吸附、进入、脱壳、基因表达与核酸复制、装配及释放等环节，不同病毒的顺序组织和机制不同。病毒感染可呈急性或持续等过程；潜伏感染是某些病毒持续存在并可再激活的一种状态。', ['能排列病毒复制的基本环节。', '能区分病毒潜伏与持续产生子代病毒的感染状态。'], Q('病毒后代颗粒形成前，将核酸和结构蛋白组织到一起的过程叫什么？', '装配', ['吸附', '脱壳', '核酸复制'], '装配把新产生的病毒成分组织为颗粒，与病毒进入或宿主免疫识别不同。'), Q('某病毒基因组长期保留于宿主细胞，在一定条件下可再激活，而非持续产生子代病毒，最贴近哪个概念？', '潜伏感染', ['已完全清除的既往感染', '持续产生子代病毒的慢性感染状态', '只存在暴露而从未进入宿主细胞'], '潜伏感染涉及病毒遗传物质保留和有限表达等状态，可在相应条件下再激活。'), [(7, '基因组与结构组成是理解复制过程的基础')]), ('医学真菌的结构与生长形式', '真菌学', '真菌学', '真菌为真核生物，常见生长形式包括酵母样细胞和菌丝等；部分具有形态转换。真菌细胞壁与细菌不同，细胞膜中的甾醇组成也是理解其生物学与药物靶点的基础。', ['能区分真菌和细菌的细胞组织。', '能识别酵母样与菌丝生长形式。'], Q('与典型细菌相比，真菌的重要细胞学特征是什么？', '具有真正细胞核及膜性细胞器', ['无真正细胞核，仅有拟核', '细胞壁主要由肽聚糖构成', '主要依赖二分裂且均无膜性细胞器'], '真菌属于真核生物，结构组织与原核细菌不同。'), Q('一种真菌可在不同条件下呈酵母样或菌丝样形态，说明什么？', '同一真菌可能具有条件相关的形态转换', ['两种形态必然是两个互不相关物种', '形态改变说明真核细胞转变为原核细胞', '酵母样细胞不能属于可形成菌丝的同一真菌'], '形态是重要识别线索，但部分真菌具有多形态或双相特点，不能机械用单一形态划分物种。'), [(1, '真核与原核的区别是理解真菌结构的基础')]), ('传染源、传播途径与易感宿主', '感染过程', '微生物感染与免疫的共同原则', '感染传播需要结合微生物来源、传播途径、进入部位及宿主易感性分析。暴露不等同于已感染，感染也不必然产生有症状疾病，预防措施应与具体传播环节对应。', ['能区分暴露、感染和发病。', '能按传播环节分析基础预防原理。'], Q('接触到某病原体但尚无感染证据，最准确的状态描述是什么？', '发生暴露', ['已经确定发病', '已形成终身保护', '必然属于无症状感染'], '暴露指接触机会，是否感染及是否发病还需后续证据。'), Q('某措施主要减少带有病原体的飞沫到达易感者，其主要针对哪一环节？', '传播途径', ['直接增强宿主特异性免疫记忆', '清除已经进入组织的全部病原体', '改变宿主对病原体的遗传易感性'], '该措施主要减少传播机会；具体防护选择仍需依据相应病原和场景要求。'), [(5, '理解宿主与微生物互动才能区分暴露、感染及疾病')]), ('消毒、灭菌与生物安全原则', '方法与证据', '病原微生物实验室生物安全；防治原则', '消毒降低或灭活规定条件下的病原微生物，灭菌以去除或杀灭全部活微生物包括芽孢为目标。效果取决于对象、方法及验证条件；实验活动应按机构分级管理执行。', ['能区分消毒与灭菌的目标。', '能说明方法效果与对象和条件有关。'], Q('以去除或杀灭包括细菌芽孢在内全部活微生物为目标的过程叫什么？', '灭菌', ['一般消毒的全部同义词', '仅清除可见污物的清洁', '仅降低细菌繁殖速度的抑菌'], '灭菌的目标比一般消毒更严格，实际过程需按规定条件和验证要求实施。'), Q('为什么不能把“看起来干净”直接视为“已经无菌”？', '肉眼清洁与微生物去除或灭活是不同证据层次', ['可见污物去除后，芽孢就一定不再存在', '没有异味即可代替微生物质量验证', '清洁只要完成，就等同于灭菌目标已经实现'], '可见污物、微生物数量与存活状态不同；无菌要求相应过程和质量保证证据。'), [(3, '微生物存活和生长条件有助于区分处理目标', 'soft')]), ('标本质量、培养与核酸检测的证据边界', '方法与证据', '特异性诊断共同原则', '微生物检测需要合适标本及质量控制。培养、核酸与抗原抗体检测测量的对象不同；污染、定植、时间窗及既往干预可影响解释，应结合多个证据判断。', ['能比较培养和核酸检测测量对象。', '能识别污染及标本来源对解释的影响。'], Q('通常情况下，核酸检测直接测量的主要对象是什么？', '特定核酸靶序列', ['所有微生物的存活能力', '全部抗体的保护效力', '全部感染造成的组织损伤程度'], '核酸检测可提供靶标存在的证据，但不能自动等同于活病原体或全部临床状态。'), Q('某样本检出常见皮肤定植菌，但采样和转运质量存疑，最应考虑哪种解释风险？', '污染可能使检出结果与目标部位真实情况不一致', ['该菌名足以排除任何污染', '核酸检测永远不受污染影响', '检测结果足以直接决定个体全部治疗'], '标本质量是解释前提，应结合来源、质量控制和其他证据区分污染、定植与感染。'), [(6, '定植与感染的区别直接影响标本结果解释'), (3, '培养结果受培养条件和可培养性限制', 'soft')])]
